// UI8 gates (declarative UI tooling), one executable per gate (FUSE_UI8_GATE):
//   markup_roundtrip     — .fuseui cooked and loaded == loaded from source (tree, styles, layout, bindings, two-way,
//                          actions), no JSON / CSS / expression parsing on the cooked path
//   binding_bytecode     — compiled vs cooked bytecode agree on random expressions x random models; corrupt bytecode
//                          (stack underflow, bad op, bad variable, deep stack, bad two-way) is rejected
//   style_cooked         — .fusestyle cooked == parsed (computed styles over a tree, tokens, var(), states, grid),
//                          deterministic output, truncated / corrupt blobs rejected
//   hot_reload_identity  — reload keeps NodeHandles of id nodes (outside connections, focus, edit text survive),
//                          moves them, rebuilds changed classes, destroys removed ids, no node leak, syntax error keeps
//                          the old tree
//   inspector            — overlay does not move app layout, picks the deepest app node, click / arrows select,
//                          describe() fields, closes cleanly (node count back), screenshot
//   cooked_registration  — registration list generated by fuse_ui_cook at build time: exactly the classes the
//                          documents use (+ internal deps); a context with only those loads them; others are absent
//   markup_fuzz          — mutated .fuseui / .fusestyle / cooked blobs / expressions: no crash, no node leak
#include "fuse/ui/doc/cook.hpp"
