const char* g_out = nullptr;

std::string load(const char* name) {
    std::string s;
    if (!readTextFile((std::string(FUSE_UI_TEST_DATA) + "/" + name).c_str(), s)) {
        std::fprintf(stderr, "missing test data %s\n", name);
        std::exit(2);
    }
    return s;
}
void savePng(UiContext& ui, const char* name) {
    if (!g_out) return;
    ui.update(0.f);
    Image img;
    img.resize(int(ui.viewport().w), int(ui.viewport().h), 0u);
    CpuRasterizer r;
    r.setGlyphAtlas(ui.atlas().pixels(), ui.atlas().size());
    r.render(ui.drawList(), img);
    for (u32& p : img.pixels) p |= 0xFF000000u;
    const std::string path = std::string(g_out) + "/" + name;
    stbi_write_png(path.c_str(), img.width, img.height, 4, img.pixels.data(), img.width * 4);
    std::printf("wrote %s\n", path.c_str());
}
std::string colorStr(const Color& c) {
    char b[64];
    std::snprintf(b, sizeof b, "%.3f,%.3f,%.3f,%.3f", c.r, c.g, c.b, c.a);
    return b;
}
/// Everything observable about a subtree.
std::string dump(const UiContext& ui, NodeHandle n, int depth = 0) {
    char b[256];
    const ComputedStyle& cs = ui.computed(n);
    const Rect r = ui.rect(n);
    std::snprintf(b, sizeof b, "%*s%s#%s [%s] v=%g c=%d d=%d vis=%d rect=%g,%g,%g,%g fs=%g pad=%g op=%g ", depth * 2, "",
                  std::string(ui.registry().get(ui.classOf(n)).name).c_str(), std::string(ui.idOf(n)).c_str(),
                  std::string(ui.text(n)).c_str(), double(ui.value(n)), ui.checked(n), ui.disabled(n), cs.visible,
                  double(r.x), double(r.y), double(r.w), double(r.h), double(cs.fontSize), double(cs.padding.l), double(cs.opacity));
    std::string out = b;
    out += "bg=" + colorStr(cs.background) + " fg=" + colorStr(cs.color) + "\n";
    for (NodeHandle c = ui.firstChild(n); ui.alive(c); c = ui.nextSibling(c)) out += dump(ui, c, depth + 1);
    return out;
}
void setup(UiContext& ui) {
    w::install(ui);
}
std::span<const u8> bytes(const std::vector<u8>& v) { return {v.data(), v.size()}; }

void seedModel(Model& m) {
    m.set("player.health", 30.0);
    m.set("player.maxHealth", 40.0);
    m.set("player.name", std::string_view("Odin"));
    m.set("audio.volume", 0.25);
    m.set("audio.mute", 0.0);
    m.set("busy", 0.0);
}

// ---------------------------------------------------------------------------------------------------------------
int markupRoundtrip() {
    const std::string src = load("settings.fuseui");
    CookInfo info;
    auto cooked = cookDocument(src, &info);
    UI_CHECK(cooked.has_value());
    if (!cooked) return finish("fuse_ui_markup_roundtrip");
    UI_CHECK(isCookedDocument(bytes(*cooked)));
    UI_CHECK_EQ(info.nodes, 9u);
    UI_CHECK_EQ(info.bindings, 7u);
    UI_CHECK(info.instructions >= 10u);
    std::printf("settings.fuseui: %zu text bytes -> %zu cooked bytes, %u nodes, %u bindings, %u instructions\n",
                src.size(), cooked->size(), info.nodes, info.bindings, info.instructions);
    auto cls = cookedClasses(bytes(*cooked));
    UI_CHECK(cls && *cls == info.classes);
    UI_CHECK((info.classes == std::vector<std::string>{"button", "checkbox", "combobox", "label", "lineedit", "panel", "slider"}));

    UiContext a({.viewport = {480, 420}, .font = &font()}), b({.viewport = {480, 420}, .font = &font()});
    setup(a);
    setup(b);
    Model ma, mb;
    seedModel(ma);
    seedModel(mb);
    auto da = Document::load(a, src, &ma);
    const u64 compilesBefore = Expr::compileCount();
    auto db = Document::loadCooked(b, bytes(*cooked), &mb);
    UI_CHECK_EQ(Expr::compileCount(), compilesBefore); // no expression parsing on the cooked path
    UI_CHECK(da.has_value() && db.has_value());
    if (!da || !db) return finish("fuse_ui_markup_roundtrip");
    UI_CHECK_EQ((*da)->bindingCount(), (*db)->bindingCount());
    a.update();
    b.update();
    UI_CHECK_EQ(dump(a, (*da)->root()), dump(b, (*db)->root()));
    // style sheet came through cooked: .hp colour #ffcc66
    const Color hp = b.computed(b.find("hp")).color;
    UI_CHECK(std::fabs(hp.r - 1.f) < 1e-3f && std::fabs(hp.g - 0.8f) < 1e-3f);
    // same behaviour: model changes, two-way edits, actions
    int actA = 0, actB = 0;
    (*da)->onAction([&](std::string_view n, NodeHandle, const SignalArgs&) { actA += n == "save"; });
    (*db)->onAction([&](std::string_view n, NodeHandle, const SignalArgs&) { actB += n == "save"; });
    for (Model* m : {&ma, &mb}) {
        m->set("player.health", 12.0);
        m->set("audio.mute", 1.0);
    }
    UI_CHECK_EQ((*da)->refresh(), (*db)->refresh());
    a.setValue(a.find("vol"), 0.75f, true);
    b.setValue(b.find("vol"), 0.75f, true);
    UI_CHECK_EQ(ma.number("audio.volume"), mb.number("audio.volume"));
    UI_CHECK(std::fabs(mb.number("audio.volume") - 0.75) < 1e-6);
    (*da)->refresh();
    (*db)->refresh();
    a.update();
    b.update();
    UI_CHECK_EQ(dump(a, (*da)->root()), dump(b, (*db)->root()));
    UI_CHECK_EQ(std::string(b.text(b.find("hp"))), std::string("HP 30%"));
    for (UiContext* u : {&a, &b}) {
        const Rect r = u->rect(u->find("save"));
        u->pointerMove({r.x + 4, r.y + 4});
        u->pointerDown({r.x + 4, r.y + 4});
        u->pointerUp({r.x + 4, r.y + 4});
        u->update();
    }
    UI_CHECK_EQ(actA, 1);
    UI_CHECK_EQ(actB, 1);
    // errors: cooking a bad binding reports the binding; a non-cooked blob is rejected
    auto bad = cookDocument(R"({"fuseui":1,"root":{"class":"label","text":"{1 +}"}})");
    UI_CHECK(!bad && bad.error().path.find("binding") != std::string::npos);
    std::vector<u8> junk(64, 7);
    UI_CHECK(!Document::loadCooked(b, bytes(junk), &mb));
    // a document with no bindings needs no model
    auto plain = cookDocument(R"({"fuseui":1,"root":{"class":"panel","children":[{"class":"button","text":"Hi"}]}})");
    UI_CHECK(plain && Document::loadCooked(b, bytes(*plain), nullptr).has_value());
    return finish("fuse_ui_markup_roundtrip");
}

// ---------------------------------------------------------------------------------------------------------------
struct Rng {
    u64 s;
    u32 next() { s ^= s << 13; s ^= s >> 7; s ^= s << 17; return u32(s); }
    u32 below(u32 n) { return n ? next() % n : 0; }
    double unit() { return double(next() & 0xFFFFFF) / double(0xFFFFFF); }
};
std::string randomExpr(Rng& r, int depth) {
    static const char* vars[] = {"a", "b.c", "hp", "max", "flag"};
    static const char* bin[] = {"+", "-", "*", "/", "%", "<", "<=", ">", ">=", "==", "!=", "&&", "||"};
    if (depth > 4 || r.below(3) == 0) {
        if (r.below(2)) return vars[r.below(5)];
        char b[32];
        std::snprintf(b, sizeof b, "%g", double(r.below(200)) / 4.0);
        return b;
    }
    switch (r.below(4)) {
    case 0: return "-" + randomExpr(r, depth + 1);
    case 1: return "!(" + randomExpr(r, depth + 1) + ")";
    default: return "(" + randomExpr(r, depth + 1) + " " + bin[r.below(13)] + " " + randomExpr(r, depth + 1) + ")";
    }
}
int bindingBytecode() {
    Rng rng{0x9E3779B97F4A7C15ull};
    UiContext ui({.viewport = {320, 200}, .font = &font()});
    setup(ui);
    u32 compared = 0, mismatches = 0;
    for (int round = 0; round < 60; ++round) {
        // one document with 8 random numeric bindings (labels render "{expr:4}")
        std::vector<std::string> exprs;
        std::string json = R"({"fuseui":1,"root":{"class":"panel","children":[)";
        for (int i = 0; i < 8; ++i) {
            exprs.push_back(randomExpr(rng, 0));
            json += std::string(i ? "," : "") + R"({"class":"label","id":"e)" + std::to_string(i) + R"(","text":"{)" +
                    exprs.back() + R"(:4}"})";
        }
        json += "]}}";
        auto cooked = cookDocument(json);
        UI_CHECK(cooked.has_value());
        if (!cooked) { std::fprintf(stderr, "%s\n", json.c_str()); continue; }
        Model ms, mc;
        auto ds = Document::load(ui, json, &ms);
        UiContext ui2({.viewport = {320, 200}, .font = &font()});
        setup(ui2);
        auto dc = Document::loadCooked(ui2, bytes(*cooked), &mc);
        UI_CHECK(ds && dc);
        if (!ds || !dc) continue;
        for (int trial = 0; trial < 20; ++trial) {
            for (const char* v : {"a", "b.c", "hp", "max", "flag"}) {
                const double x = rng.below(4) == 0 ? 0.0 : (rng.unit() - 0.5) * 100.0;
                ms.set(v, x);
                mc.set(v, x);
            }
            (*ds)->refresh();
            (*dc)->refresh();
            for (int i = 0; i < 8; ++i) {
                const std::string id = "e" + std::to_string(i);
                ++compared;
                if (ui.text(ui.find(id)) != ui2.text(ui2.find(id))) {
                    if (++mismatches < 5)
                        std::fprintf(stderr, "mismatch %s: '%s' vs '%s'\n", exprs[i].c_str(),
                                     std::string(ui.text(ui.find(id))).c_str(), std::string(ui2.text(ui2.find(id))).c_str());
                }
            }
        }
    }
    UI_CHECK_EQ(mismatches, 0u);
    std::printf("compared %u evaluations\n", compared);
    UI_CHECK(compared >= 9000u);

    // corrupt bytecode: locate the instruction stream of "{a + 2}" and break it in targeted ways
    auto cooked = cookDocument(R"({"fuseui":1,"root":{"class":"label","text":"{a + 2}"}})");
    UI_CHECK(cooked.has_value());
    if (cooked) {
        // instruction stream: count=3, [Var(1) idx(0)] [Num(0) f64] [Add(2)]
        const std::vector<u8>& c = *cooked;
        std::size_t at = std::string::npos;
        for (std::size_t i = 0; i + 4 < c.size(); ++i)
            if (c[i] == 3 && c[i + 1] == 0 && c[i + 2] == 0 && c[i + 3] == 0 && c[i + 4] == u8(Expr::Op::Var)) { at = i; break; }
        UI_CHECK(at != std::string::npos);
        if (at != std::string::npos) {
            auto tryLoad = [&](std::vector<u8> blob) {
                Model m;
                UiContext u({.viewport = {100, 100}, .font = &font()});
                setup(u);
                return Document::loadCooked(u, bytes(blob), &m).has_value();
            };
            UI_CHECK(tryLoad(c)); // intact
            std::vector<u8> x = c;
            x[at + 4] = u8(Expr::Op::Add); // starts with a binary op: underflow
            UI_CHECK(!tryLoad(x));
            x = c;
            x[at + 4] = 0xEE; // unknown op
            UI_CHECK(!tryLoad(x));
            x = c;
            x[at + 5] = 9; // variable index out of the name table
            UI_CHECK(!tryLoad(x));
            x = c;
            x[at + 4 + 5 + 9] = u8(Expr::Op::Num); // last op pushes: stack ends at 3
            UI_CHECK(!tryLoad(x));
            x = c;
            x.resize(at + 7); // truncated
            UI_CHECK(!tryLoad(x));
        }
    }
    return finish("fuse_ui_binding_bytecode");
}

