int styleCooked() {
    const std::string css = load("theme.fusestyle");
    std::vector<StyleDiagnostic> diags;
    auto cooked = cookStyle(css, &diags);
    UI_CHECK(cooked.has_value());
    if (!cooked) return finish("fuse_ui_style_cooked");
    UI_CHECK(diags.size() >= 2u); // the .bogus rule's bad declarations
    UI_CHECK(isCookedStyle(bytes(*cooked)));
    auto again = cookStyle(css);
    UI_CHECK(again && *again == *cooked); // deterministic
    auto sheet = loadCookedStyle(bytes(*cooked));
    auto parsed = StyleSheet::parse(css);
    UI_CHECK(sheet && parsed);
    if (!sheet || !parsed) return finish("fuse_ui_style_cooked");
    UI_CHECK_EQ(sheet->rules().size(), parsed->rules().size());
    UI_CHECK_EQ(sheet->tokens().size(), parsed->tokens().size());
    std::printf("theme.fusestyle: %zu text bytes -> %zu cooked bytes, %zu rules, %zu tokens\n", css.size(), cooked->size(),
                sheet->rules().size(), sheet->tokens().size());
    auto build = [](UiContext& ui) {
        const NodeHandle card = w::panel(ui, ui.root(), "settings");
        ui.addClass(card, "card");
        w::label(ui, card, "Title");
        const NodeHandle hp = w::label(ui, card, "HP", "hp");
        ui.addClass(hp, "hp");
        w::button(ui, card, "Save", "save");
        const NodeHandle off = w::button(ui, card, "Off", "off");
        ui.setDisabled(off, true);
        const NodeHandle cb = w::checkBox(ui, card, "Mute", true, "mute");
        (void)cb;
        const NodeHandle grid = w::panel(ui, card, "grid");
        ui.addClass(grid, "grid");
        for (int i = 0; i < 6; ++i) w::panel(ui, grid);
    };
    UiContext a({.viewport = {400, 360}, .font = &font()}), b({.viewport = {400, 360}, .font = &font()});
    a.addStyleSheet(std::move(*parsed));
    b.addStyleSheet(std::move(*sheet));
    w::registerTierA(a);
    w::registerTierA(b);
    build(a);
    build(b);
    a.pointerMove(a.rect(a.root()).w > 0 ? Vec2{-1, -1} : Vec2{});
    a.update();
    b.update();
    const std::string da = dump(a, a.root()), db = dump(b, b.root());
    UI_CHECK_EQ(da, db);
    const ComputedStyle& card = b.computed(b.find("settings"));
    UI_CHECK(std::fabs(card.padding.l - 10.f) < 1e-4f); // var(--pad)
    UI_CHECK(std::fabs(b.computed(b.find("hp")).color.r - 1.f) < 1e-3f); // var(--accent) via #settings .hp
    UI_CHECK(std::fabs(b.computed(b.find("off")).opacity - 0.4f) < 1e-4f); // :disabled
    // hover state on both
    for (UiContext* u : {&a, &b}) {
        const Rect r = u->rect(u->find("save"));
        u->pointerMove({r.x + 3, r.y + 3});
        u->update();
    }
    UI_CHECK_EQ(dump(a, a.root()), dump(b, b.root()));
    // corrupt / truncated blobs are rejected, never crash
    u32 rejected = 0;
    for (std::size_t n = 0; n < cooked->size(); n += 7) {
        std::vector<u8> t(cooked->begin(), cooked->begin() + std::ptrdiff_t(n));
        rejected += !loadCookedStyle(bytes(t)).has_value();
    }
    UI_CHECK_EQ(rejected, u32((cooked->size() + 6) / 7));
    std::vector<u8> x = *cooked;
    x[0] = 'X';
    UI_CHECK(!loadCookedStyle(bytes(x)));
    x = *cooked;
    x.push_back(0);
    UI_CHECK(!loadCookedStyle(bytes(x))); // trailing bytes
    return finish("fuse_ui_style_cooked");
}

// ---------------------------------------------------------------------------------------------------------------
const char* kV1 = R"({ "fuseui": 1, "root": { "class": "panel", "id": "main", "classes": ["v1"], "children": [
  { "class": "label", "id": "title", "text": "Hello" },
  { "class": "lineedit", "id": "name", "text": "" },
  { "class": "slider", "id": "vol", "value": "{=vol}" },
  { "class": "panel", "children": [ { "class": "label", "id": "deep", "text": "deep" }, { "class": "label", "text": "anon" } ] },
  { "class": "button", "id": "ok", "text": "OK", "on": { "clicked": "ok" } },
  { "class": "checkbox", "id": "gone", "text": "Gone" }
] } })";
const char* kV2 = R"({ "fuseui": 1, "root": { "class": "panel", "id": "main", "classes": ["v2"], "children": [
  { "class": "label", "id": "title", "text": "Hello v2", "classes": ["big"] },
  { "class": "label", "id": "deep", "text": "deep moved" },
  { "class": "lineedit", "id": "name", "text": "" },
  { "class": "dial", "id": "vol", "value": "{=vol}" },
  { "class": "label", "id": "added", "text": "new" },
  { "class": "panel", "id": "footer", "children": [ { "class": "button", "id": "ok", "text": "OK!", "on": { "clicked": "ok2" } } ] }
] } })";
u32 subtreeCount(const UiContext& ui, NodeHandle n) {
    u32 c = 1;
    for (NodeHandle k = ui.firstChild(n); ui.alive(k); k = ui.nextSibling(k)) c += subtreeCount(ui, k);
    return c;
}
int hotReloadIdentity() {
    UiContext ui({.viewport = {480, 360}, .font = &font()});
    setup(ui);
    Model m;
    m.set("vol", 0.4);
    auto d = Document::load(ui, kV1, &m);
    UI_CHECK(d.has_value());
    if (!d) return finish("fuse_ui_hot_reload_identity");
    Document& doc = **d;
    std::vector<std::string> actions;
    doc.onAction([&](std::string_view a, NodeHandle, const SignalArgs&) { actions.emplace_back(a); });
    ui.update();
    const NodeHandle main = ui.find("main"), title = ui.find("title"), name = ui.find("name"), vol = ui.find("vol"),
                     deep = ui.find("deep"), ok = ui.find("ok"), gone = ui.find("gone");
    // game-side state: an outside connection, focus + typed text, a user-data tag
    int outsideClicks = 0;
    ui.connect(ok, SignalKind::Clicked, [&](UiContext&, NodeHandle, const SignalArgs&) { ++outsideClicks; });
    ui.setUserData(title, 0xC0FFEEu);
    ui.setFocus(name, FocusReason::Keyboard);
    ui.textInput("Odin");
    ui.update();
    UI_CHECK_EQ(std::string(ui.text(name)), std::string("Odin"));
    const u32 before = ui.nodeCount(), v1Count = subtreeCount(ui, main);

    UI_CHECK(doc.reload(kV2).has_value());
    ui.update();
    UI_CHECK_EQ(doc.reusedCount(), 5u); // main, title, name, deep, ok
    UI_CHECK(ui.find("main") == main && doc.root() == main);
    UI_CHECK(ui.find("title") == title && ui.find("name") == name && ui.find("deep") == deep && ui.find("ok") == ok);
    UI_CHECK(ui.find("vol") != vol && !ui.alive(vol)); // slider -> dial: rebuilt
    UI_CHECK(!ui.alive(gone) && !ui.find("gone"));
    UI_CHECK(ui.alive(ui.find("added")));
    UI_CHECK(ui.parent(ok) == ui.find("footer"));
    UI_CHECK(ui.parent(deep) == main);
    UI_CHECK_EQ(std::string(ui.text(title)), std::string("Hello v2")); // display text follows the markup
    UI_CHECK_EQ(std::string(ui.text(ok)), std::string("OK!"));
    UI_CHECK(ui.hasClass(title, "big") && ui.hasClass(main, "v2") && !ui.hasClass(main, "v1"));
    UI_CHECK_EQ(ui.userData(title), 0xC0FFEEu);
    UI_CHECK_EQ(std::string(ui.text(name)), std::string("Odin")); // edited text kept
    UI_CHECK(ui.focused() == name);
    UI_CHECK(std::fabs(ui.value(ui.find("vol")) - 0.4f) < 1e-5f); // bound: from the model
    // order follows the new markup
    std::vector<std::string> order;
    for (NodeHandle c = ui.firstChild(main); ui.alive(c); c = ui.nextSibling(c)) order.emplace_back(ui.idOf(c));
    UI_CHECK((order == std::vector<std::string>{"title", "deep", "name", "vol", "added", "footer"}));
    // no leaks: everything outside the document is unchanged (the reload holder and dropped nodes are gone)
    UI_CHECK_EQ(ui.nodeCount() - subtreeCount(ui, main), before - v1Count);
    const u32 afterV2 = ui.nodeCount();
    // outside connection and the new action both fire on a click
    ui.update();
    const Rect r = ui.rect(ok);
    ui.pointerMove({r.x + 3, r.y + 3});
    ui.pointerDown({r.x + 3, r.y + 3});
    ui.pointerUp({r.x + 3, r.y + 3});
    ui.update();
    UI_CHECK_EQ(outsideClicks, 1);
    UI_CHECK((actions == std::vector<std::string>{"ok2"}));
    // reloading the same text again keeps every id node and the node count
    UI_CHECK(doc.reload(kV2).has_value());
    ui.update();
    UI_CHECK_EQ(doc.reusedCount(), 8u);
    UI_CHECK_EQ(ui.nodeCount(), afterV2);
    for (int i = 0; i < 20; ++i) (void)doc.reload(i % 2 ? kV1 : kV2);
    (void)doc.reload(kV2);
    ui.update();
    UI_CHECK_EQ(ui.nodeCount(), afterV2);
    UI_CHECK(ui.find("ok") == ok && ui.find("title") == title);
    // a syntax error leaves the tree alone
    UI_CHECK(!doc.reload("{ \"fuseui\": 1, \"root\": { ").has_value());
    UI_CHECK(ui.alive(ok) && ui.find("ok") == ok && ui.nodeCount() == afterV2);
    return finish("fuse_ui_hot_reload_identity");
}

