int inspector() {
    UiContext ui({.viewport = {800, 480}, .font = &font()});
    setup(ui);
    Model m;
    seedModel(m);
    auto d = Document::load(ui, load("settings.fuseui"), &m);
    UI_CHECK(d.has_value());
    if (!d) return finish("fuse_ui_inspector");
    ui.setCss((*d)->root(), "margin", "24px");
    ui.update();
    const u32 baseNodes = ui.nodeCount();
    std::vector<Rect> rects;
    std::vector<NodeHandle> app;
    auto collect = [&](auto&& self, NodeHandle n) -> void {
        app.push_back(n);
        rects.push_back(ui.rect(n));
        for (NodeHandle c = ui.firstChild(n); ui.alive(c); c = ui.nextSibling(c)) self(self, c);
    };
    collect(collect, (*d)->root());

    w::Inspector insp(ui);
    insp.setEnabled(true);
    ui.update();
    insp.update();
    ui.update();
    UI_CHECK(insp.enabled());
    UI_CHECK(ui.nodeCount() > baseNodes);
    bool same = true;
    for (std::size_t i = 0; i < app.size(); ++i) {
        const Rect r = ui.rect(app[i]);
        same &= r.x == rects[i].x && r.y == rects[i].y && r.w == rects[i].w && r.h == rects[i].h;
    }
    UI_CHECK(same);
    // pick: the save button, the slider, the root panel's padding area
    const NodeHandle save = ui.find("save"), vol = ui.find("vol"), root = (*d)->root();
    const Rect sr = ui.rect(save);
    const Vec2 onSave{sr.x + sr.w * 0.5f, sr.y + sr.h * 0.5f};
    UI_CHECK(insp.pick(onSave) == save);
    const Rect vr = ui.rect(vol);
    UI_CHECK(insp.pick({vr.x + 2, vr.y + vr.h * 0.5f}) == vol);
    const Rect rr = ui.rect(root);
    UI_CHECK(insp.pick({rr.x + 3, rr.y + 3}) == root);
    UI_CHECK(insp.pick({790, 470}) == ui.root());
    // the info panel sits over the app on the right: picking under it still finds app nodes, never inspector nodes
    for (f32 y = 10; y < 470; y += 37)
        for (f32 x = 10; x < 790; x += 41) UI_CHECK(!insp.owns(insp.pick({x, y})));
    // hover then click selects; app does not get the click
    int clicks = 0;
    ui.connect(save, SignalKind::Clicked, [&](UiContext&, NodeHandle, const SignalArgs&) { ++clicks; });
    UI_CHECK(!insp.pointerMove(onSave));
    UI_CHECK(insp.hovered() == save);
    UI_CHECK(insp.pointerDown(onSave));
    UI_CHECK(insp.selected() == save);
    UI_CHECK_EQ(clicks, 0);
    const std::string desc = insp.describe(save);
    UI_CHECK(desc.find("button#save") != std::string::npos);
    UI_CHECK(desc.find("path: root#root > panel#settings") != std::string::npos);
    UI_CHECK(desc.find("role: Button") != std::string::npos || desc.find("role: button") != std::string::npos);
    UI_CHECK(desc.find("text: \"Save\"") != std::string::npos);
    char box[64];
    std::snprintf(box, sizeof box, "box: %.0f, %.0f  %.0f x %.0f", sr.x, sr.y, sr.w, sr.h);
    UI_CHECK(desc.find(box) != std::string::npos);
    // arrows walk the tree
    insp.keyDown(Key::Up);
    UI_CHECK(insp.selected() == root);
    insp.keyDown(Key::Down);
    UI_CHECK(insp.selected() == ui.firstChild(root));
    insp.keyDown(Key::Right);
    UI_CHECK(insp.selected() == ui.nextSibling(ui.firstChild(root)));
    insp.keyDown(Key::Left);
    UI_CHECK(insp.selected() == ui.firstChild(root));
    insp.select(ui.find("vol"));
    insp.pointerMove(onSave);
    ui.update();
    insp.update();
    savePng(ui, "inspector.png");
    // hover box tracks the hovered node
    // disabled: all inspector nodes gone, app untouched
    UI_CHECK(insp.keyDown(Key::Escape));
    UI_CHECK(!insp.enabled());
    ui.update();
    UI_CHECK_EQ(ui.nodeCount(), baseNodes + 1u); // + the overlay layer it created
    UI_CHECK(!insp.pointerDown(onSave));
    for (int i = 0; i < 5; ++i) { insp.setEnabled(true); insp.update(); ui.update(); insp.setEnabled(false); }
    ui.update();
    UI_CHECK_EQ(ui.nodeCount(), baseNodes + 1u);
    return finish("fuse_ui_inspector");
}

